int hidp_setup_hid_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
	struct hid_device *hid_dev;
	int err = -ENOMEM;

	hid_dev = kzalloc(sizeof(*hid_dev), GFP_KERNEL);
	if (!hid_dev)
		goto err_out;

	session->hid_dev = hid_dev;

	hid_dev->vendor = req->vendor;
	hid_dev->product = req->product;
	hid_dev->bus = BUS_HID;
	hid_dev->dev_class = HID_CLASS;
	hid_dev->uniq = kstrdup(req->name, GFP_KERNEL);
	hid_dev->name = kstrdup(req->name, GFP_KERNEL);
	hid_dev->driver = NULL;
	hid_dev->status = 0;

	if (hid_check_blacklist(hid_dev)) {
		err = -EPERM;
		goto err_free_hid_dev;
	}

	/* Additional session setup logic if required */
	return 0;

err_free_hid_dev:
	kfree(hid_dev->uniq);
	kfree(hid_dev->name);
	kfree(hid_dev);
err_out:
	return err;
}

int hidp_init_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
	struct hid_device *hid_dev;

	hid_dev = kzalloc(sizeof(*hid_dev), GFP_KERNEL);
	if (!hid_dev)
		return -ENOMEM;

	session->hid_dev = hid_dev;
	session->read_buffer = kmalloc(req->buffer_size, GFP_KERNEL);
	if (!session->read_buffer) {
		kfree(hid_dev);
		return -ENOMEM;
	}

	if (copy_from_user(&hid_dev->vendor, &req->vendor,
			   sizeof(hid_dev->vendor)) ||
	    copy_from_user(&hid_dev->product, &req->product,
			   sizeof(hid_dev->product)) ||
	    copy_from_user(&hid_dev->country, &req->country,
			   sizeof(hid_dev->country))) {
		kfree(hid_dev);
		kfree(session->read_buffer);
		return -EFAULT;
	}

	if (hid_dev_is_blacklisted(hid_dev)) {
		kfree(hid_dev);
		kfree(session->read_buffer);
		return -EPERM;
	}

	hid_dev->setup_complete = 1;

	return 0;
}

int hidp_init_session(struct hidp_session *session, struct hidp_connadd_req *req) {
    int ret = -ENOMEM;

    session->rd_data = kmalloc(req->rd_data_size, GFP_KERNEL);
    if (!session->rd_data)
        goto out;

    if (copy_from_user(session->rd_data, req->rd_data, req->rd_data_size))
        goto out_free_rd_data;

    session->hid_dev = hid_allocate_device();
    if (!session->hid_dev)
        goto out_free_rd_data;

    session->hid_dev->vendor = req->vendor;
    session->hid_dev->product = req->product;
    session->hid_dev->version = req->version;
    session->hid_dev->country = req->country;

    if (hid_is_blacklisted(session->hid_dev)) {
        ret = -ENODEV;
        goto out_free_hid_dev;
    }

    ret = hid_register_device(session->hid_dev);
    if (ret)
        goto out_free_hid_dev;

    return 0;

out_free_hid_dev:
    hid_free_device(session->hid_dev);
out_free_rd_data:
    kfree(session->rd_data);
out:
    return ret;
}

int hidp_setup_hid_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
	struct hid_device *hdev;

	session->hid_read_data = kmalloc(req->rd_size, GFP_KERNEL);
	if (!session->hid_read_data)
		return -ENOMEM;

	if (copy_from_user(session->hid_read_data, req->rd_data, req->rd_size)) {
		kfree(session->hid_read_data);
		return -EFAULT;
	}

	hdev = hid_allocate_device();
	if (!hdev) {
		kfree(session->hid_read_data);
		return -ENOMEM;
	}

	hdev->vendor = req->device->vendor;
	hdev->product = req->device->product;
	hdev->version = req->device->version;
	hdev->country = req->device->country;

	if (hid_is_blacklist(hdev)) {
		hid_destroy_device(hdev);
		kfree(session->hid_read_data);
		return -EINVAL;
	}

	session->hid_dev = hdev;

	return 0;
}

int hidp_setup_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
	struct hid_device *hid;
	int err = -ENOMEM;

	hid = kzalloc(sizeof(struct hid_device), GFP_KERNEL);
	if (!hid)
		goto out;

	session->hid = hid;
	hid->vendor = req->vendor;
	hid->product = req->product;
	hid->country = req->country;

	if (hid_is_blacklisted(hid)) {
		err = -ENODEV;
		goto out_free;
	}

	session->rd_data = kzalloc(HIDP_MAX_HID_DESCRIPTOR_SIZE, GFP_KERNEL);
	if (!session->rd_data)
		goto out_free;

	err = copy_from_user(session->rd_data, req->rd_data, req->rd_length) ? -EFAULT : 0;
	if (err)
		goto out_cleanup;

	/* Continue with other setup steps if any */
	goto success;

out_cleanup:
	kfree(session->rd_data);
	session->rd_data = NULL;
out_free:
	kfree(hid);
out:
	return err;

success:
	return 0;
}
